source.javascript:
function rotate(matrix) {
  const rows = matrix.length
  const cols = matrix[0].length
  const out = []
  for (let c = 0; c < cols; c++) {
    const row = []
    for (let r = rows - 1; r >= 0; r--) row.push(matrix[r][c])
    out.push(row)
  }
  return out
}

source.typescript:
function rotate(matrix: number[][]): number[][] {
  const rows = matrix.length
  const cols = matrix[0].length
  const out: number[][] = []
  for (let c = 0; c < cols; c++) {
    const row: number[] = []
    for (let r = rows - 1; r >= 0; r--) row.push(matrix[r][c])
    out.push(row)
  }
  return out
}
